        context: { amount: 150 }
      });
      console.log(`Status: ${response1.status}, Result: ${response1.body.result}`);
      console.log(`Expected: true, Actual: ${response1.body.result}`);
      console.log(response1.body.result === true ? '✓ PASS\n' : '✗ FAIL\n');

      // Test 2
