      const response2 = await request(app).post('/check').send({
        rule: 'ctx.user.role === "admin" && req.method === "POST"',
        context: { user: { role: 'admin' } }
      });
      console.log(`Status: ${response2.status}, Result: ${response2.body.result}`);
      console.log(`Expected: true, Actual: ${response2.body.result}`);
      console.log(response2.body.result === true ? '✓ PASS\n' : '✗ FAIL\n');

      // Test 3
      console.log('Test 3: Missing rule parameter');
      const response3 = await request(app).post('/check').send({
        context: { amount: 50 }
      });
      console.log(`Status: ${response3.status}, Error: ${response3.body.error}`);
      console.log(`Expected: 400, Actual: ${response3.status}`);
      console.log(response3.status === 400 ? '✓ PASS\n' : '✗ FAIL\n');

      // Test 4
      console.log('Test 4: Invalid JavaScript syntax');
      const response4 = await request(app).post('/check').send({
        rule: 'ctx.amount > // invalid syntax',
        context: { amount: 50 }
      });
      console.log(`Status: ${response4.status}, Error: ${response4.body.error}`);
      console.log(`Expected: 500, Actual: ${response4.status}`);
      console.log(response4.status === 500 ? '✓ PASS\n' : '✗ FAIL\n');

      // Test 5
      console.log('Test 5: Falsy condition');
      const response5 = await request(app).post('/check').send({
        rule: 'ctx.count < 10',
