const http = require('http');

// Test data for various scenarios
const testCases = [
  {
    name: 'Simple comparison (true)',
    rule: 'ctx.amount > 100',
    context: { amount: 150 },
    expected: true
  },
  {
    name: 'Simple comparison (false)',
    rule: 'ctx.amount > 100',
    context: { amount: 50 },
    expected: false
  },
  {
    name: 'Complex rule with && operator',
    rule: 'ctx.user.role === "admin" && ctx.user.active === true',
    context: { user: { role: 'admin', active: true } },
    expected: true
  },
  {
    name: 'Complex rule with || operator',
    rule: 'ctx.user.role === "admin" || ctx.user.role === "moderator"',
    context: { user: { role: 'moderator' } },
    expected: true
  },
  {
    name: 'Access nested properties',
    rule: 'ctx.data.items[0].price > 50',
    context: { data: { items: [{ price: 75 }, { price: 30 }] } },
    expected: true
  },
  {
    name: 'String comparison',
    rule: 'ctx.name === "test"',
    context: { name: 'test' },
    expected: true
  }
];

// Function to make HTTP request
function makeRequest(testCase, callback) {
  const postData = JSON.stringify({
    rule: testCase.rule,
    context: testCase.context
  });

  const options = {
    hostname: 'localhost',
    port: 3000,
    path: '/check',
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'Content-Length': Buffer.byteLength(postData)
    }
  };

  const req = http.request(options, (res) => {
    let data = '';
    res.on('data', (chunk) => {
      data += chunk;
    });
    res.on('end', () => {
      callback(null, {
        status: res.statusCode,
        data: JSON.parse(data)
      });
    });
  });

  req.on('error', (err) => {
    callback(err);
  });

  req.write(postData);
  req.end();
}

// Start the server first
