// The server is already started in app.js with app.listen(3000)
// So we just need to wait a moment for it to start
setTimeout(() => {
  console.log('Server should be running. Starting tests...\n');

  let passed = 0;
  let failed = 0;

  // Run tests sequentially
  function runTest(index) {
    if (index >= testCases.length) {
      console.log(`\n=== Test Summary ===`);
      console.log(`Passed: ${passed}`);
      console.log(`Failed: ${failed}`);
      console.log(`Total: ${testCases.length}`);
      return;
    }

    const testCase = testCases[index];
    console.log(`Test ${index + 1}: ${testCase.name}`);
    console.log(`Rule: "${testCase.rule}"`);
    console.log(`Context: ${JSON.stringify(testCase.context)}`);

    makeRequest(testCase, (err, result) => {
      if (err) {
        console.log(`Error: ${err.message}`);
        failed++;
      } else {
        if (result.status === 200 && result.data.result === testCase.expected) {
          console.log(`✓ PASS - Result: ${result.data.result}, Expected: ${testCase.expected}`);
          passed++;
