  let passed = 0;
  let failed = 0;

  function runTest(testCase) {
    const postData = JSON.stringify({
      rule: testCase.rule,
      context: testCase.context
    });

    const options = {
      hostname: 'localhost',
      port: 3000,
      path: '/check',
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Content-Length': Buffer.byteLength(postData)
      }
    };

    const req = http.request(options, (res) => {
      let data = '';
      res.on('data', (chunk) => {
        data += chunk;
      });
      res.on('end', () => {
        completed++;

        let parsedData;
        try {
          parsedData = JSON.parse(data);
        } catch (e) {
          parsedData = { error: 'Invalid JSON response' };
        }

        console.log(`Test: ${testCase.name}`);

        if (testCase.expectedError) {
          if (res.statusCode === testCase.expectedStatus) {
            console.log(`✓ PASS - Got expected ${res.statusCode} status`);
            passed++;
          } else {
            console.log(`✗ FAIL - Expected status ${testCase.expectedStatus}, got ${res.statusCode}`);
            console.log(`  Response: ${data}`);
            failed++;
          }
        } else {
          if (res.statusCode === 200 && parsedData.result === testCase.expected) {
            console.log(`✓ PASS - Result: ${parsedData.result}, Expected: ${testCase.expected}`);
            passed++;
          } else {
            console.log(`✗ FAIL - Status: ${res.statusCode}, Result: ${parsedData.result}, Expected: ${testCase.expected}`);
            console.log(`  Response: ${JSON.stringify(parsedData, null, 2)}`);
            failed++;
          }
        }
        console.log('---');

        // Check if all tests are done
        if (completed === testCases.length) {
          console.log(`\n=== Test Summary ===`);
          console.log(`Passed: ${passed}`);
          console.log(`Failed: ${failed}`);
          console.log(`Total: ${testCases.length}`);
          server.close();
          process.exit(failed > 0 ? 1 : 0);
        }
      });
    });

    req.on('error', (err) => {
      completed++;
      console.log(`Test: ${testCase.name}`);
      console.log(`✗ FAIL - Request error: ${err.message}`);
      failed++;
      console.log('---');

      if (completed === testCases.length) {
        console.log(`\n=== Test Summary ===`);
        console.log(`Passed: ${passed}`);
        console.log(`Failed: ${failed}`);
        console.log(`Total: ${testCases.length}`);
        server.close();
        process.exit(1);
      }
    });

    req.write(postData);
    req.end();
  }

  // Run all tests
  console.log(`Running ${testCases.length} tests...\n`);
  for (const testCase of testCases) {
    runTest(testCase);
  }
});

